int 
dtb_spinbox_chg_type_msg_initialize(DtbMessageData instance)
{
    char	*tmp_txt;
    if (instance->initialized)
    {
        return 0;
    }
    instance->initialized = True;

    instance->type = XmDIALOG_WARNING;
    instance->title = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 26, 40, "Application Builder"));
    instance->message = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 26, 70, "Changing Spin Box type to Numeric will\ncause StringList items to be deleted."));
    instance->action1_label = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 26, 42, "Change"));
    instance->action1_callback = (XtCallbackProc) NULL;
    instance->action2_label = (XmString) NULL;
    instance->action2_callback = (XtCallbackProc) NULL;
    instance->action3_label = (XmString) NULL;
    instance->action3_callback = (XtCallbackProc) NULL;
    instance->cancel_button = True;
    instance->cancel_callback = (XtCallbackProc) NULL;
    instance->help_button = True;
    tmp_txt = CATGETS(Dtb_project_catd, 26, 72, "If the Spin Box type is changed to Numeric, its\nchildren must be digits. Therefore, the Spin\nBox's StringList items will be deleted.");
    instance->help_data.help_text = XtMalloc(strlen(tmp_txt)+1);
    strcpy(instance->help_data.help_text, tmp_txt);
    
    instance->help_data.help_volume = "";
    instance->help_data.help_locationID = "";
    instance->default_button = DTB_CANCEL_BUTTON;
    return 0;
}



static int 
dtb_spinbox_prop_dialog_create(
    DtbSpinboxPropDialogInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    Display	*display= (parent == NULL? NULL:XtDisplay(parent));
    Arg	args[8];	/* need 3 args (add 5 to be safe) */
    int	n = 0;
    String	title_str = NULL;
    static DtbObjectHelpDataRec	help_data = {
        "",
        "AppBuilder",
        "ABPropsEditor",
    };
    char *tmp_txt;
    
    if (instance->prop_dialog == NULL) {
        title_str = XtNewString(CATGETS(Dtb_project_catd, 26, 1, "Spin Box Property Editor"));
        n = 0;
        XtSetArg(args[n], XmNallowShellResize, True);  ++n;
        XtSetArg(args[n], XmNtitle, title_str);  ++n;
        XtSetArg(args[n], XmNbackground, dtb_cvt_string_to_pixel(parent, "white"));  ++n;
        instance->prop_dialog =
            XmCreateDialogShell(parent,
                "dtb_spinbox_prop_dialog", args, n);
        XtFree(title_str);
        title_str = NULL;
    }
    if (instance->prop_dialog == NULL)
        return -1;

    if (instance->prop_dialog_shellform == NULL) {
        instance->prop_dialog_shellform =
            XtVaCreateWidget("dtb_spinbox_prop_dialog_shellform",
                xmFormWidgetClass,
                instance->prop_dialog,
                XmNdefaultPosition, False,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNbackground, dtb_cvt_string_to_pixel(instance->prop_dialog, "white"),
                NULL);
        /*
         * Add help callback
         */
        tmp_txt = CATGETS(Dtb_project_catd, 26, 67, "This Property Editor allows Spin Box object attributes to be examined or altered.\n");
        help_data.help_text = XtMalloc(strlen(tmp_txt)+1);
        strcpy(help_data.help_text,tmp_txt);
        
        XtAddCallback(instance->prop_dialog_shellform,
            XmNhelpCallback, dtb_help_dispatch,
            (XtPointer)&help_data);
    }
    if (instance->prop_dialog_shellform == NULL)
        return -1;

    if (instance->prop_dialog_panedwin == NULL) {
        instance->prop_dialog_panedwin =
            XtVaCreateWidget("prop_dialog_panedwin",
                xmPanedWindowWidgetClass,
                instance->prop_dialog_shellform,
                XmNbottomOffset, 0,
                XmNbottomPosition, 100,
                XmNbottomAttachment, XmATTACH_POSITION,
                XmNrightOffset, 0,
                XmNrightPosition, 100,
                XmNrightAttachment, XmATTACH_POSITION,
                XmNleftOffset, 0,
                XmNleftPosition, 0,
                XmNleftAttachment, XmATTACH_POSITION,
                XmNtopOffset, 0,
                XmNtopPosition, 0,
                XmNtopAttachment, XmATTACH_POSITION,
                XmNsashWidth, 1,
                XmNsashHeight, 1,
                XmNspacing, 0,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNbackground, dtb_cvt_string_to_pixel(instance->prop_dialog_shellform, "white"),
                NULL);
    }
    if (instance->prop_dialog_panedwin == NULL)
        return -1;

    if (instance->prop_dialog_form == NULL) {
        instance->prop_dialog_form =
            XtVaCreateWidget("prop_dialog_form",
                xmFormWidgetClass,
                instance->prop_dialog_panedwin,
                XmNallowResize, True,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNresizePolicy, XmRESIZE_ANY,
                XmNbackground, dtb_cvt_string_to_pixel(instance->prop_dialog_panedwin, "white"),
                NULL);
    }
    if (instance->prop_dialog_form == NULL)
        return -1;

    return 0;
}



